CREATE PROCEDURE dbo.sp_RegistrarVenta
    @ClienteID INT,
    @Folio VARCHAR(30),
    @ProductoID INT,
    @Cantidad DECIMAL(18,4),
    @PrecioUnitario DECIMAL(18,4),
    @PresentacionProductoID BIGINT = NULL,
    @Serie VARCHAR(10) = NULL,
    @ClienteDireccionID INT = NULL,
    @ListaPrecioID INT = NULL,
    @CondicionPagoID SMALLINT = NULL,
    @MonedaID SMALLINT = NULL,
    @TipoCambio DECIMAL(18,6) = 1,
    @DescuentoPorcentaje DECIMAL(9,4) = 0,
    @TasaImpuesto DECIMAL(9,4) = NULL,
    @FechaVencimiento DATE = NULL,
    @Observaciones VARCHAR(1000) = NULL,
    @ReferenciaExterna VARCHAR(100) = NULL,
    @NumeroFactura VARCHAR(50) = NULL,
    @UUIDFactura VARCHAR(50) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRANSACTION;
    BEGIN TRY
        DECLARE @VentaID BIGINT;
        DECLARE @Renglon INT = 1;
        DECLARE @Subtotal DECIMAL(18,2);
        DECLARE @DescuentoImporte DECIMAL(18,2);
        DECLARE @ImpuestoImporte DECIMAL(18,2);
        DECLARE @Total DECIMAL(18,2);
        DECLARE @SaldoPendiente DECIMAL(18,2);
        DECLARE @EstatusVentaID TINYINT;
        DECLARE @StockActual DECIMAL(18,4);
        DECLARE @EsInventariable BIT;
        DECLARE @FactorConversionInventario DECIMAL(18,6);
        DECLARE @CantidadInventario DECIMAL(18,4);
        DECLARE @TriggerExiste BIT = 0;

        IF NOT EXISTS (SELECT 1 FROM dbo.Cliente_Catalogo WHERE ClienteID = @ClienteID AND Activo = 1)
            RAISERROR('Cliente no existe o esta inactivo.', 16, 1);

        IF NOT EXISTS (SELECT 1 FROM dbo.Producto_Catalogo WHERE ProductoID = @ProductoID AND Activo = 1)
            RAISERROR('Producto no existe o esta inactivo.', 16, 1);

        IF @MonedaID IS NULL
            SELECT @MonedaID = MonedaID FROM dbo.Cliente_Catalogo WHERE ClienteID = @ClienteID;

        IF @ListaPrecioID IS NULL
            SELECT @ListaPrecioID = ListaPrecioID FROM dbo.Cliente_Catalogo WHERE ClienteID = @ClienteID;

        IF @CondicionPagoID IS NULL
            SELECT @CondicionPagoID = CondicionPagoID FROM dbo.Cliente_Catalogo WHERE ClienteID = @ClienteID;

        IF @TasaImpuesto IS NULL
            SELECT @TasaImpuesto = ISNULL(TasaImpuesto,0) FROM dbo.Producto_Catalogo WHERE ProductoID = @ProductoID;

        IF @MonedaID IS NULL
            SET @MonedaID = 1;

        SELECT
            @StockActual = ISNULL(StockActual,0),
            @EsInventariable = ISNULL(EsInventariable,1)
        FROM dbo.Producto_Catalogo
        WHERE ProductoID = @ProductoID;

        IF @PresentacionProductoID IS NOT NULL
        BEGIN
            SELECT @FactorConversionInventario = ISNULL(FactorConversionInventario,1)
            FROM dbo.Producto_Presentaciones
            WHERE PresentacionProductoID = @PresentacionProductoID
              AND ProductoID = @ProductoID;

            IF @FactorConversionInventario IS NULL
                RAISERROR('La presentacion no corresponde al producto.', 16, 1);
        END
        ELSE
        BEGIN
            SET @FactorConversionInventario = 1;
        END

        SET @CantidadInventario = @Cantidad * ISNULL(@FactorConversionInventario,1);

        IF ISNULL(@EsInventariable,1) = 1
        BEGIN
            IF ISNULL(@StockActual,0) < ISNULL(@CantidadInventario,0)
                RAISERROR('Stock insuficiente para realizar la venta.', 16, 1);
        END

        SELECT @EstatusVentaID = EstatusVentaID
        FROM dbo.Venta_Estatus
        WHERE Descripcion = 'CONFIRMADA';

        IF @EstatusVentaID IS NULL
            SET @EstatusVentaID = 3;

        SET @Subtotal = ROUND(@Cantidad * @PrecioUnitario, 2);
        SET @DescuentoImporte = ROUND(@Subtotal * (ISNULL(@DescuentoPorcentaje,0) / 100.0), 2);
        SET @ImpuestoImporte = ROUND((@Subtotal - @DescuentoImporte) * (ISNULL(@TasaImpuesto,0) / 100.0), 2);
        SET @Total = ROUND((@Subtotal - @DescuentoImporte) + @ImpuestoImporte, 2);
        SET @SaldoPendiente = @Total;

        INSERT INTO dbo.Venta_Encabezado
        (
            Serie, Folio, FechaVenta, FechaVencimiento,
            ClienteID, ClienteDireccionID, ListaPrecioID, CondicionPagoID,
            MonedaID, TipoCambio, EstatusVentaID,
            Subtotal, DescuentoTotal, ImpuestoTotal, Total, TotalPagado, SaldoPendiente,
            Observaciones, ReferenciaExterna, NumeroFactura, UUIDFactura,
            Activo, CreatedAt, CreatedBy
        )
        VALUES
        (
            @Serie, @Folio, SYSDATETIME(), @FechaVencimiento,
            @ClienteID, @ClienteDireccionID, @ListaPrecioID, @CondicionPagoID,
            @MonedaID, ISNULL(@TipoCambio,1), @EstatusVentaID,
            @Subtotal, @DescuentoImporte, @ImpuestoImporte, @Total, 0, @SaldoPendiente,
            @Observaciones, @ReferenciaExterna, @NumeroFactura, @UUIDFactura,
            1, SYSDATETIME(), CONVERT(VARCHAR(100), SESSION_CONTEXT(N'UsuarioID'))
        );

        SET @VentaID = SCOPE_IDENTITY();

        INSERT INTO dbo.Venta_Detalle
        (
            VentaID, Renglon, ProductoID, PresentacionProductoID,
            Cantidad, PrecioUnitario,
            DescuentoPorcentaje, DescuentoImporte,
            TasaImpuesto, ImpuestoImporte,
            Observaciones, Activo, CreatedAt, CreatedBy
        )
        VALUES
        (
            @VentaID, @Renglon, @ProductoID, @PresentacionProductoID,
            @Cantidad, @PrecioUnitario,
            ISNULL(@DescuentoPorcentaje,0), @DescuentoImporte,
            ISNULL(@TasaImpuesto,0), @ImpuestoImporte,
            @Observaciones, 1, SYSDATETIME(), CONVERT(VARCHAR(100), SESSION_CONTEXT(N'UsuarioID'))
        );

        IF EXISTS (SELECT 1 FROM sys.triggers WHERE name = 'TR_ActualizarStockVenta')
            SET @TriggerExiste = 1;

        IF @TriggerExiste = 0 AND ISNULL(@EsInventariable,1) = 1
        BEGIN
            UPDATE dbo.Producto_Catalogo
            SET StockActual = StockActual - @CantidadInventario
            WHERE ProductoID = @ProductoID;
        END

        COMMIT TRANSACTION;

        SELECT
            'OK' AS Resultado,
            @VentaID AS VentaID,
            @Folio AS Folio,
            @Total AS Total,
            @CantidadInventario AS CantidadDescontadaInventario;
    END TRY
    BEGIN CATCH
        ROLLBACK TRANSACTION;

        SELECT
            'ERROR' AS Resultado,
            ERROR_MESSAGE() AS ErrorDetalle;
    END CATCH
END

