    @AtencionA VARCHAR(150) = NULL,
    @Observaciones VARCHAR(1000) = NULL,
    @InstruccionesEntrega VARCHAR(1000) = NULL,
    @ReferenciaExterna VARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRANSACTION;
    BEGIN TRY
        DECLARE @PedidoID BIGINT;
        DECLARE @Renglon INT = 1;
        DECLARE @Subtotal DECIMAL(18,2);
        DECLARE @DescuentoImporte DECIMAL(18,2);
        DECLARE @ImpuestoImporte DECIMAL(18,2);
