            RAISERROR('Producto no existe o esta inactivo.', 16, 1);

        IF @CotizacionID IS NOT NULL
        BEGIN
            IF NOT EXISTS (SELECT 1 FROM dbo.Venta_Cotizaciones WHERE CotizacionID = @CotizacionID AND Activo = 1)
                RAISERROR('La cotizacion relacionada no existe.', 16, 1);
        END

