        SET @DescuentoImporte = ROUND(@Subtotal * (ISNULL(@DescuentoPorcentaje,0) / 100.0), 2);
        SET @ImpuestoImporte = ROUND((@Subtotal - @DescuentoImporte) * (ISNULL(@TasaImpuesto,0) / 100.0), 2);
