            Cantidad, CantidadSurtida, PrecioUnitario,
            DescuentoPorcentaje, DescuentoImporte,
            TasaImpuesto, ImpuestoImporte,
            Observaciones, Activo, CreatedAt, CreatedBy
        )
        VALUES
