        BEGIN
            UPDATE dbo.Producto_Catalogo
            SET StockActual = StockActual - @CantidadInventario
            WHERE ProductoID = @ProductoID;
        END

        COMMIT TRANSACTION;

        SELECT
            'OK' AS Resultado,
            @VentaID AS VentaID,
            @Folio AS Folio,
            @Total AS Total,
            @CantidadInventario AS CantidadDescontadaInventario;
    END TRY
    BEGIN CATCH
        ROLLBACK TRANSACTION;

        SELECT
            'ERROR' AS Resultado,
            ERROR_MESSAGE() AS ErrorDetalle;
    END CATCH
END
